const envelope = $json;
const expectedSecret = String($env.TELEGRAM_FORWARD_SECRET || '');
if (!expectedSecret || String(envelope.headers?.['x-telegram-forward-secret'] || '') !== expectedSecret) return [];
const event = envelope.body && typeof envelope.body === 'object' ? envelope.body : envelope;
const chatId = event.message?.chat?.id ?? event.callback_query?.message?.chat?.id;
if (chatId === undefined || String(chatId) !== String($env.ALLOWED_CHAT_ID || '')) return [];
const text = String(event.message?.text || '').trim();
const supportedLanguages = ['en', 'pl', 'ru', 'uk'];
const ui_language = supportedLanguages.includes(event.ui_language) ? event.ui_language : 'pl';
let route = '';
let id = '';
if (/^\/help(?:@\w+)?(?:\s.*)?$/i.test(text)) route = 'help';
else if (/^\/lang(?:@\w+)?(?:\s.*)?$/i.test(text)) {
  route = 'lang';
  event.requested_language = (text.match(/^\/lang(?:@\w+)?\s+(\S+)/i) || [])[1]?.toLowerCase() || '';
}
else if (/^\/search(?:@\w+)?(?:\s.*)?$/i.test(text)) {
  route = 'search';
  event.search_query = text.replace(/^\/search(?:@\w+)?/i, '').trim();
}
else if (/^\/(?:start|next)(?:@\w+)?(?:\s.*)?$/i.test(text)) route = 'next';
else {
  const add = text.match(/^\/add(?:@\w+)?\s+(?:\[[^\]]*\]\()?((?:https?:\/\/)[^\s)]+)\)?\s*$/i);
  const pasted = text.match(/^\/text(?:@\w+)?\s+([a-f0-9]{12})\s+([\s\S]{1,4000})$/i);
  if (add) { route = 'add'; event.vacancy_url = add[1]; }
  else if (pasted) { route = 'text'; id = pasted[1].toLowerCase(); event.vacancy_text = pasted[2].trim(); }
}
if (!route && event.callback_query) {
  const data = event.callback_query.data || '';
  if (data === 'stop') route = 'stop';
  else {
    const action = data.match(/^(apply|skip|unmodified):([a-f0-9]{12})$/i);
    if (action) { route = action[1].toLowerCase(); id = action[2].toLowerCase(); }
  }
}
if (!route) return [];
return [{ json: { ...event, ui_language, chat_id: String(chatId), route, id } }];
